0.3 0.2 0.5
</input>
<input>
3 3
0.2 0.3 0.5
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include "bits/stdc++.h"

#define forn(i, n) for (int i = 0; i < (int)n; i++)
#define ford(i, n) for (int i = (int)n - 1; i >= 0; i--)
#define forab(i, a, b) for (int i = (int)a; i < (int)b; i++)
#define X first
#define Y second
#define pb push_back
#define mp make_pair
#define all(x) (x).begin(), (x).end()

template<typename T> inline T sqr(T x)
{
    return x*x; 
}                    

using namespace std;

typedef vector<int> vi;
typedef pair<int, int> pii;
typedef long long ll;
typedef long double ld;

const ld eps = 1e-12;
const int INF = (int)1E9;
const int MAXN = 21;
const int MAXMASK = 1 << MAXN;

bool eq(ld a, ld b) {
	return fabs(a - b) < eps;
}

int n, N, k;
ld p[MAXN];
ld ans[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> k;
    N = n;
    forn(i, n) {
        cin >> p[i];
    }

    // Handle special case: if k >= n, all videos will always be in cache
    if (k >= n) {
        forn(i, n) {
            cout << fixed << setprecision(20) << 1.0 << " \n"[i == n-1];
        }
        return 0;
    }

    // Filter out videos with probability 0
    vector<int> valid;
    forn(i, n) {
        if (!eq(p[i], 0.0)) {
            valid.push_back(i);
        }
    }

    n = valid.size();
    if (n == 0) {
        forn(i, N) {
            cout << fixed << setprecision(20) << 0.0 << " \n"[i == N-1];
        }
        return 0;
    }

    // If after filtering we have n <= k, all remaining videos will always be in cache
    if (n <= k) {
        forn(i, N) {
            if (eq(p[i], 0.0)) {
                ans[i] = 0.0;
            } else {
                ans[i] = 1.0;
            }
        }
        forn(i, N) {
            cout << fixed << setprecision(20) << ans[i] << " \n"[i == N-1];
        }
        return 0;
    }

    // Precompute binomial coefficients
    ll cnk[MAXN][MAXN] = {0};
    cnk[0][0] = 1;
    forab(i, 1, MAXN) {
        cnk[i][0] = 1;
        forab(j, 1, i+1) {
            cnk[i][j] = cnk[i-1][j-1] + cnk[i-1][j];
        }
    }

    // Compute coefficients for inclusion-exclusion
    vector<ld> coeff(k, 0.0);
    for (int j = 0; j < k; j++) {
        ld sum = 0.0;
        for (int i = 0; i <= k - 1 - j; i++) {
            if (i % 2 == 0) {
                sum += cnk[n - j - 1][i];
            } else {
                sum -= cnk[n - j - 1][i];
            }
        }
        coeff[j] = sum;
    }

    // Iterate through all subsets of videos (bitmask)
    int mmask = 1 << n;
    vector<ld> pSum(mmask, 0.0);
    vector<int> mass(mmask, 0);

    forn(mask, mmask) {
        pSum[mask] = 0;
        mass[mask] = 0;
        forn(i, n) {
            if ((mask >> i) & 1) {
                pSum[mask] += p[valid[i]];
                mass[mask]++;
            }
        }
    }

    // Calculate probability for each video
    forn(idx, n) {
        int i = valid[idx];
        ld curAns = 0.0;

        forn(mask, mmask) {
            int j = mass[mask];
            // Check if subset does not contain video i and has size between 1 and k-1
            if (j >= 1 && j <= k - 1 && ((mask >> idx) & 1) == 0) {
                if (!eq(1.0 - pSum[mask], 0.0)) {
                    curAns += coeff[j] * (pSum[mask] / (1.0 - pSum[mask]));
                }
            }
        }

        curAns += 1.0;  // Add 1 for the case when the video itself is in the subset
        curAns *= p[i];

        ans[i] = curAns;
    }

    // Output results for all videos (including those with 0 probability)
    forn(i, N) {
        if (eq(p[i], 0.0)) {
            ans[i] = 0.0;
        }
        cout << fixed << setprecision(20) << ans[i] << " \n"[i == N-1];
    }

    return 0;
}
</source_code>
